// Content for Equal Partners (node g55, ages 22+, Chapter 7) — NEW v2 build to GDD 55 (mechanic-embodying), the
// EQUAL-HOME heart of Chapter 7: the most unequal place in most lives is the home. 84 researched, India-grounded
// scenarios across see-the-load → helping-vs-owning → share-it-fairly → two-careers → keep-it-equal →
// tools-and-help, each encoded as one of the shared v2 play actions (branch / strike-rewrite / sort / reflect /
// role-play / match / spot) — no binary "tap the right card". Lead: branch (your move), strike-rewrite (bust the
// myth), role-play (say it). The signature move reframes a man's role from "helping" to OWNING an equal share —
// the planning and remembering (the invisible mental load), not just the handed-out chores. Five+ themes: see the
// whole load (surface the invisible mental & care work), helping vs owning (the core reframe), share it fairly
// (an explicit, fair split of chores, care & money-time), two careers (dual-career fairness; whose job "flexes"
// shouldn't default to gender), keep it equal (renegotiate as life changes), tools/help. Everyone gains: an equal
// home is happier and healthier for both. Even-handed, engages men as equal OWNERS, never anti-men, and never
// shames any current arrangement; where inequality becomes coercive control it is named as abuse and routed to
// Respect at Home (g56) and help (181, 1091, 112). Builds on Equalize (g26); sets up Equal Parents (g62). India
// has one of the world's largest unpaid-care gaps — women do ~2.6× more unpaid care than men even in dual-income
// homes — and in-laws / joint families often reinforce gendered expectations. gameId "equal-partners".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"ep-001","cat":"see-the-load","type":"strike-rewrite","hook":"\"The mental load isn't real work.\"","myth":{"un":"The mental load isn't real work.","re":"Planning, remembering, anticipating and keeping track is real, exhausting cognitive labour.","why":"Invisible work is still work, and it tires you out."},"relearn":"The mental load, planning and remembering, is real, exhausting cognitive labour.","persona":"Pooja","source":"mental load is real"},
  {"id":"ep-002","cat":"see-the-load","type":"sort","hook":"Sort: visible chore, or the invisible mental load?","items":[{"id":"a","text":"Washing the dishes"},{"id":"b","text":"Remembering everyone's appointments"},{"id":"c","text":"Cooking dinner"},{"id":"d","text":"Noticing the milk's running out"}],"bins":[{"id":"visible","label":"Visible chore"},{"id":"mental","label":"Mental load"}],"key":{"a":"visible","b":"mental","c":"visible","d":"mental"},"relearn":"Dishes and cooking are visible chores; remembering appointments and noticing needs is the invisible mental load.","persona":"any","source":"visible vs invisible"},
  {"id":"ep-003","cat":"see-the-load","type":"spot","hook":"Spot the mental-load task hiding behind a 'simple' chore.","scene":[{"id":"a","text":"Knowing what groceries are needed and when","trick":true},{"id":"b","text":"Physically carrying the bags","trick":false},{"id":"c","text":"Tracking which bills are due","trick":true}],"why":"Knowing what's needed and tracking bills is the mental load; carrying bags is the visible part.","relearn":"Knowing what's needed and tracking it is the mental load behind 'simple' chores.","persona":"any","source":"hidden load"},
  {"id":"ep-004","cat":"see-the-load","type":"strike-rewrite","hook":"\"We split the chores 50/50, so our home is equal.\"","myth":{"un":"We split the chores 50/50, so we're equal.","re":"Visible chores are only part of it; the invisible mental load has to be shared too.","why":"You can split tasks and still leave all the managing to one person."},"relearn":"Splitting visible chores isn't enough; the invisible mental load must be shared too.","persona":"any","source":"chores aren't the whole load"},
  {"id":"ep-005","cat":"see-the-load","type":"sort","hook":"Sort: part of the unseen load, or genuinely shared?","items":[{"id":"a","text":"One person plans every meal and list"},{"id":"b","text":"Both notice what the home needs"},{"id":"c","text":"One person remembers all the dates"},{"id":"d","text":"Both track the bills"}],"bins":[{"id":"unseen","label":"Unseen load on one"},{"id":"shared","label":"Genuinely shared"}],"key":{"a":"unseen","b":"shared","c":"unseen","d":"shared"},"relearn":"One person planning and remembering everything is an unseen load; both noticing and tracking is shared.","persona":"any","source":"who carries it"},
  {"id":"ep-006","cat":"see-the-load","type":"strike-rewrite","hook":"\"Housework and childcare are naturally the woman's job.\"","myth":{"un":"Housework and childcare are naturally the woman's job.","re":"They're shared work; nothing about them is 'naturally' gendered.","why":"Capability at home has nothing to do with gender."},"relearn":"Housework and childcare are shared work, not 'naturally' the woman's job.","persona":"any","source":"not naturally gendered"},
  {"id":"ep-007","cat":"see-the-load","type":"branch","hook":"You sense your partner is carrying far more of the home than you'd realised.","options":[{"text":"Ask them to walk you through the full, invisible load","consequence":"You start to actually see it.","outcome":"sees-it","best":true},{"text":"Assume it's balanced because you do 'your bit'","consequence":"Asking them to show you the full invisible load reveals what 'doing your bit' misses."}],"debrief":"The first step to fairness is genuinely seeing the whole load, visible and invisible.","relearn":"Ask your partner to show you the full, invisible load; you can't share what you can't see.","persona":"Karthik","source":"learning to see it"},
  {"id":"ep-008","cat":"see-the-load","type":"strike-rewrite","hook":"\"In a dual-income home, the housework must already be even.\"","myth":{"un":"In a dual-income home the housework is even.","re":"Even in dual-income homes, women typically do far more unpaid care, often around 2.6 times as much.","why":"Earning equally rarely means sharing the home equally."},"relearn":"Even in dual-income homes, women usually do far more unpaid care; it isn't automatically even.","persona":"Sneha","source":"the dual-income gap"},
  {"id":"ep-009","cat":"see-the-load","type":"spot","hook":"Spot the sign that the load is unequal.","scene":[{"id":"a","text":"One partner has to be asked for everything","trick":true},{"id":"b","text":"Both just notice and act","trick":false},{"id":"c","text":"One partner is the household 'manager'","trick":true}],"why":"Having to be asked, and one person being the 'manager', signal an unequal load; both noticing doesn't.","relearn":"If one partner is the 'manager' who must ask the other, the load is unequal.","persona":"any","source":"signs of imbalance"},
  {"id":"ep-010","cat":"see-the-load","type":"sort","hook":"Sort: emotional/mental labour, or not?","items":[{"id":"a","text":"Worrying whether a child is okay"},{"id":"b","text":"Mopping the floor"},{"id":"c","text":"Keeping the peace with in-laws"},{"id":"d","text":"Taking out the rubbish"}],"bins":[{"id":"mental","label":"Mental/emotional labour"},{"id":"physical","label":"Physical task"}],"key":{"a":"mental","b":"physical","c":"mental","d":"physical"},"relearn":"Worrying about a child and managing in-law relations is emotional labour; mopping and rubbish are physical tasks.","persona":"any","source":"emotional labour"},
  {"id":"ep-011","cat":"see-the-load","type":"branch","hook":"You want to truly understand your home's full workload together.","options":[{"text":"List everything, including the invisible work, together","consequence":"You make the whole load visible.","outcome":"visible","best":true},{"text":"Just count the obvious chores","consequence":"Listing everything, including the invisible managing, reveals the true load that counting chores misses."}],"debrief":"Writing down the full load, visible and invisible, is how a couple finally sees what's really being carried.","relearn":"List everything together, including the invisible work, to see the full load.","persona":"any","source":"make it visible"},
  {"id":"ep-012","cat":"see-the-load","type":"match","hook":"Match the load type to an example.","pairs":[{"left":"Physical chore","right":"Cooking, cleaning"},{"left":"Mental load","right":"Planning, remembering"},{"left":"Emotional labour","right":"Keeping the peace, caring"}],"relearn":"Chores, mental load and emotional labour are three real, different parts of running a home.","persona":"any","source":"three kinds of work"},
  {"id":"ep-013","cat":"see-the-load","type":"reflect","hook":"Sam: once you can see the invisible load, you can't unsee it, and you can finally share it. Powerful?","prompt":"What do you think?","options":["Yes","I see it now","Can't unsee it"],"affirm":"Seeing the invisible load is the breakthrough; you can't share fairly what you couldn't see.","relearn":"Once you see the invisible load, you can finally share it fairly.","persona":"any","source":"seeing it"},
  {"id":"ep-014","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"Helping with the chores means I'm sharing the load equally.\"","myth":{"un":"Helping with the chores means I share the load equally.","re":"'Helping' leaves your partner as the manager who notices and delegates; true equality is owning a domain.","why":"A helper waits to be told; an owner runs it."},"relearn":"'Helping' leaves your partner managing; true equality is owning a domain, not just helping.","persona":"Karthik","source":"helping vs owning"},
  {"id":"ep-015","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"If I do the task when asked, I've done my share.\"","myth":{"un":"If I do the task when asked, I've done my share.","re":"Being asked means your partner is still carrying the mental load; owning means doing it without being asked.","why":"The asking is itself the unequal work."},"relearn":"Doing a task when asked isn't equal; owning means noticing and doing it unprompted.","persona":"Karthik","source":"without being asked"},
  {"id":"ep-016","cat":"helping-vs-owning","type":"branch","hook":"You want to genuinely take an equal share, not just pitch in when asked.","options":[{"text":"Own whole domains end-to-end: notice, plan, do","consequence":"You lift the mental load, not just the chore.","outcome":"owns-it","best":true},{"text":"Keep waiting to be told what to do","consequence":"Owning a domain end-to-end, noticing and planning, lifts the mental load that waiting-to-be-told leaves behind."}],"debrief":"Owning whole domains, not waiting for instructions, is what actually shares the mental load.","relearn":"Own whole domains end-to-end, notice, plan, do, rather than waiting to be told.","persona":"Karthik","source":"own a domain"},
  {"id":"ep-017","cat":"helping-vs-owning","type":"role-play","hook":"Your partner keeps thanking you for 'helping', and you want to reframe it.","setup":"Claim ownership, warmly. Say:","yourLine":[{"text":"\"This isn't me helping you, it's mine to run, you shouldn't have to manage it.\"","best":true},{"text":"\"Yeah, happy to help out.\""}],"relearn":"Reframe 'helping' as owning: 'this is mine to run, you shouldn't have to manage it.'","persona":"Karthik","source":"reframing it"},
  {"id":"ep-018","cat":"helping-vs-owning","type":"sort","hook":"Sort: owning a share, or just helping?","items":[{"id":"a","text":"Running the laundry without prompting"},{"id":"b","text":"Doing it only when reminded"},{"id":"c","text":"Tracking and restocking groceries yourself"},{"id":"d","text":"Waiting for a list to be handed to you"}],"bins":[{"id":"owns","label":"Owning"},{"id":"helps","label":"Just helping"}],"key":{"a":"owns","b":"helps","c":"owns","d":"helps"},"relearn":"Running and tracking things yourself is owning; doing them only when reminded is just helping.","persona":"any","source":"owning vs helping"},
  {"id":"ep-019","cat":"helping-vs-owning","type":"branch","hook":"You realise your partner still has to remind you about your 'shared' tasks.","options":[{"text":"Take over the remembering, not just the doing","consequence":"You remove the reminding from their load.","outcome":"lifts-load","best":true},{"text":"Keep needing the reminders","consequence":"Taking over the remembering, not just the doing, removes the reminding that's still on their plate."}],"debrief":"If your partner still has to remind you, you've taken the task but not the mental load; own the remembering too.","relearn":"Take over the remembering, not just the doing; the reminding is part of the load.","persona":"any","source":"remove the reminding"},
  {"id":"ep-020","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"Asking him to remember things is just nagging.\"","myth":{"un":"Asking him to remember things is nagging.","re":"The need to remind is itself the unequal mental load; owning removes the need to remind.","why":"It's not nagging if he simply owned it."},"relearn":"The need to remind is the unequal mental load; owning removes it, it's not nagging.","persona":"Pooja","source":"not nagging"},
  {"id":"ep-021","cat":"helping-vs-owning","type":"role-play","hook":"You want to offer to fully own a part of the home, not just help.","setup":"Take it off their plate. Say:","yourLine":[{"text":"\"Let me fully take the kitchen and groceries, you don't have to think about it at all.\"","best":true},{"text":"\"Tell me what you need me to do.\""}],"relearn":"Offer to fully own a domain so your partner doesn't have to think about it at all.","persona":"Karthik","source":"taking it over"},
  {"id":"ep-022","cat":"helping-vs-owning","type":"branch","hook":"You're the 'good guy who helps' but your partner still seems exhausted.","options":[{"text":"Recognise that 'helping' isn't enough, and own real domains","consequence":"You address the actual exhaustion.","outcome":"growth","best":true},{"text":"Feel you've already done plenty by helping","consequence":"If your partner's still exhausted, 'helping' isn't enough; owning real domains is what relieves the load."}],"debrief":"A partner exhausted despite your 'help' is a sign the mental load is still entirely theirs; own domains to fix it.","relearn":"If your partner's still exhausted, helping isn't enough; own real domains.","persona":"Karthik","source":"good guy who helps"},
  {"id":"ep-023","cat":"helping-vs-owning","type":"reflect","hook":"Sam: the real shift is from 'how can I help you?' to 'this is simply mine'. Feel the difference?","prompt":"What do you think?","options":["Yes","Mine to own","Big difference"],"affirm":"'This is mine' instead of 'how can I help?' is the whole shift that actually shares the load.","relearn":"The shift is from 'how can I help?' to 'this is mine to own'.","persona":"any","source":"the shift"},
  {"id":"ep-024","cat":"helping-vs-owning","type":"sort","hook":"Sort: lifts your partner's mental load, or leaves it on them?","items":[{"id":"a","text":"Owning a task start to finish"},{"id":"b","text":"Asking 'what should I do?'"},{"id":"c","text":"Remembering it yourself"},{"id":"d","text":"Needing constant reminders"}],"bins":[{"id":"lifts","label":"Lifts the load"},{"id":"leaves","label":"Leaves it on them"}],"key":{"a":"lifts","b":"leaves","c":"lifts","d":"leaves"},"relearn":"Owning start-to-finish and remembering it yourself lifts the load; asking what to do and needing reminders leaves it.","persona":"any","source":"lift the load"},
  {"id":"ep-025","cat":"share-it-fairly","type":"branch","hook":"You and your partner want to divide the home load fairly.","options":[{"text":"Make an explicit, agreed split of owned domains","consequence":"You replace assumptions with fairness.","outcome":"fair","best":true},{"text":"Just let it fall where it always has","consequence":"An explicit, agreed split of owned domains is fairer than letting it default to how it's always been."}],"debrief":"Fairness comes from an explicit, agreed division, not from unspoken defaults.","relearn":"Make an explicit, agreed split of owned domains, not an assumed one.","persona":"any","source":"explicit split"},
  {"id":"ep-026","cat":"share-it-fairly","type":"sort","hook":"Sort: a fair way to divide the load, or an unfair default?","items":[{"id":"a","text":"Dividing by owned domains, agreed together"},{"id":"b","text":"Whatever the woman 'naturally' picks up"},{"id":"c","text":"Accounting for paid and unpaid hours"},{"id":"d","text":"Whoever earns less does it all"}],"bins":[{"id":"fair","label":"Fair"},{"id":"unfair","label":"Unfair default"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair"},"relearn":"Agreed owned domains and counting all hours is fair; defaulting to the woman or the lower-earner isn't.","persona":"any","source":"fair vs default"},
  {"id":"ep-027","cat":"share-it-fairly","type":"role-play","hook":"You want to open the conversation about splitting the home load fairly.","setup":"Start it openly. Say:","yourLine":[{"text":"\"Let's actually map out everything and split it fairly, the invisible stuff too.\"","best":true},{"text":"Avoid it and hope it balances out"}],"relearn":"Open the fair-split conversation, including the invisible work.","persona":"any","source":"opening the talk"},
  {"id":"ep-028","cat":"share-it-fairly","type":"branch","hook":"Your split looks even on chores, but one of you carries all the planning.","options":[{"text":"Reassign some of the planning and remembering too","consequence":"You balance the invisible load.","outcome":"balanced","best":true},{"text":"Call it even because the chores are split","consequence":"Reassigning the planning and remembering balances the invisible load that even chores leave behind."}],"debrief":"A fair split must include the planning and remembering, not just the visible tasks.","relearn":"Reassign the planning and remembering too, not just the visible chores.","persona":"any","source":"split the invisible too"},
  {"id":"ep-029","cat":"share-it-fairly","type":"sort","hook":"Sort: counts toward a fair share, or gets ignored?","items":[{"id":"a","text":"Hours of paid work"},{"id":"b","text":"Hours of unpaid home work"},{"id":"c","text":"The mental load carried"},{"id":"d","text":"Only the visible chores"}],"bins":[{"id":"counts","label":"Should count"},{"id":"ignored","label":"Often ignored"}],"key":{"a":"counts","b":"counts","c":"counts","d":"ignored"},"relearn":"Paid hours, unpaid hours and the mental load should all count; counting only visible chores ignores most of it.","persona":"any","source":"what counts"},
  {"id":"ep-030","cat":"share-it-fairly","type":"branch","hook":"One of you genuinely has more time this season than the other.","options":[{"text":"Adjust the split fairly for now, and revisit later","consequence":"You stay fair and flexible.","outcome":"flexible","best":true},{"text":"Keep a rigid split that no longer fits","consequence":"Adjusting fairly for the season, then revisiting, beats a rigid split that's stopped fitting."}],"debrief":"Fair doesn't always mean identical; it flexes with each person's real capacity, and is revisited.","relearn":"Adjust the split fairly for each season, and revisit it; fair isn't always identical.","persona":"any","source":"fair not identical"},
  {"id":"ep-031","cat":"share-it-fairly","type":"role-play","hook":"You need to renegotiate a split that's quietly become unfair.","setup":"Raise it without blame. Say:","yourLine":[{"text":"\"I think our split has drifted, can we rebalance it so it's fair again?\"","best":true},{"text":"Let resentment build silently"}],"relearn":"Raise a drifted split without blame and rebalance it.","persona":"Pooja","source":"renegotiating"},
  {"id":"ep-032","cat":"share-it-fairly","type":"match","hook":"Match the fairness move to what it does.","pairs":[{"left":"List everything together","right":"Makes the load visible"},{"left":"Assign owned domains","right":"Shares the mental load"},{"left":"Revisit regularly","right":"Keeps it fair over time"}],"relearn":"Listing, assigning domains and revisiting each move you toward a fair, shared home.","persona":"any","source":"fairness moves"},
  {"id":"ep-033","cat":"share-it-fairly","type":"sort","hook":"Sort: an agreement that lasts, or one that quietly fails?","items":[{"id":"a","text":"Clear, owned responsibilities"},{"id":"b","text":"Vague 'we'll both pitch in'"},{"id":"c","text":"A regular check-in"},{"id":"d","text":"Assuming it'll just work out"}],"bins":[{"id":"lasts","label":"Lasts"},{"id":"fails","label":"Quietly fails"}],"key":{"a":"lasts","b":"fails","c":"lasts","d":"fails"},"relearn":"Clear owned responsibilities and regular check-ins last; vague 'we'll pitch in' and assumptions quietly fail.","persona":"any","source":"what lasts"},
  {"id":"ep-034","cat":"share-it-fairly","type":"branch","hook":"In your joint family, relatives expect the home tasks to fall to the woman.","options":[{"text":"As a couple, hold your own fair arrangement","consequence":"You protect your equality within the family.","outcome":"united","best":true},{"text":"Default to what relatives expect","consequence":"Holding your own fair arrangement as a couple protects your equality within joint-family expectations."}],"debrief":"Couples can hold a fair arrangement together even amid traditional joint-family expectations.","relearn":"As a couple, hold your own fair arrangement within family expectations.","persona":"any","source":"within the joint family"},
  {"id":"ep-035","cat":"two-careers","type":"strike-rewrite","hook":"\"Her career is the one that should flex for the home.\"","myth":{"un":"Her career is the one that should flex for the home.","re":"Whose career flexes shouldn't default to gender; both careers count equally.","why":"His job isn't automatically more important."},"relearn":"Whose career flexes shouldn't default to gender; both careers count equally.","persona":"any","source":"whose career flexes"},
  {"id":"ep-036","cat":"two-careers","type":"strike-rewrite","hook":"\"His job is the 'real' one; hers is a backup.\"","myth":{"un":"His job is the real one; hers is a backup.","re":"Both partners' careers are real and matter; neither is automatically secondary.","why":"Treating one as a 'backup' devalues a whole person's work."},"relearn":"Both partners' careers are real and matter; neither is automatically a backup.","persona":"any","source":"both careers real"},
  {"id":"ep-037","cat":"two-careers","type":"branch","hook":"A family need means someone's work has to flex; you both assume it's hers.","options":[{"text":"Decide together, based on fairness, not gender","consequence":"You make a fair, conscious choice.","outcome":"fair","best":true},{"text":"Default to her career flexing","consequence":"Deciding together on fairness, not defaulting to her career flexing, is the equal approach."}],"debrief":"When a career must flex, deciding fairly together beats the default assumption that it's hers.","relearn":"Decide whose work flexes together, on fairness, not by gender default.","persona":"any","source":"deciding fairly"},
  {"id":"ep-038","cat":"two-careers","type":"sort","hook":"Sort: supports both careers, or quietly sidelines one?","items":[{"id":"a","text":"Both partners' ambitions taken seriously"},{"id":"b","text":"Assuming she'll scale back"},{"id":"c","text":"Sharing the home so both can work"},{"id":"d","text":"Treating his promotion as the priority"}],"bins":[{"id":"supports","label":"Supports both"},{"id":"sidelines","label":"Sidelines one"}],"key":{"a":"supports","b":"sidelines","c":"supports","d":"sidelines"},"relearn":"Taking both ambitions seriously and sharing the home supports both careers; assuming she scales back sidelines one.","persona":"any","source":"supporting both"},
  {"id":"ep-039","cat":"two-careers","type":"strike-rewrite","hook":"\"Whoever earns more shouldn't have to do home work.\"","myth":{"un":"Whoever earns more shouldn't do home work.","re":"Earning more doesn't exempt anyone from the home; the load is shared regardless of pay.","why":"Income doesn't buy you out of partnership."},"relearn":"Earning more doesn't exempt you from home work; the load is shared regardless of pay.","persona":"any","source":"earning isn't an exemption"},
  {"id":"ep-040","cat":"two-careers","type":"branch","hook":"Your partner has a big career opportunity that needs your support at home.","options":[{"text":"Step up at home so they can take it, as they would for you","consequence":"You support their career as an equal would.","outcome":"supportive","best":true},{"text":"Assume your work always comes first","consequence":"Stepping up so your partner can seize an opportunity, as they would for you, is real two-career equality."}],"debrief":"Equal partners take turns supporting each other's careers, rather than one always coming first.","relearn":"Step up at home so your partner's career can grow, as they would for yours.","persona":"any","source":"taking turns"},
  {"id":"ep-041","cat":"two-careers","type":"spot","hook":"Spot the dual-career fairness move.","scene":[{"id":"a","text":"Taking turns on whose work flexes","trick":false},{"id":"b","text":"Always assuming hers gives way","trick":true},{"id":"c","text":"Backing each other's ambitions","trick":false}],"why":"Taking turns and backing each other is fair; always assuming hers gives way isn't.","relearn":"Taking turns on flexing and backing each other's ambitions is dual-career fairness.","persona":"any","source":"fairness move"},
  {"id":"ep-042","cat":"two-careers","type":"reflect","hook":"Sam: when both careers are truly valued, the home arrangement follows fairly. Agree?","prompt":"What do you think?","options":["Yes","Both valued","Follows fairly"],"affirm":"Valuing both careers equally is the foundation; a fair home arrangement flows from it.","relearn":"When both careers are truly valued equally, a fair home arrangement follows.","persona":"any","source":"both valued"},
  {"id":"ep-043","cat":"keep-it-equal","type":"branch","hook":"A new baby is about to massively change your home workload.","options":[{"text":"Renegotiate the split before and after, deliberately","consequence":"You keep it equal through the change.","outcome":"equal","best":true},{"text":"Let it default back to the woman","consequence":"Deliberately renegotiating around a baby keeps it equal; left alone, it tends to default back to the woman."}],"debrief":"Big life changes like a baby are exactly when equality must be deliberately renegotiated.","relearn":"Renegotiate the split deliberately around big changes like a baby.","persona":"Nisha","source":"renegotiate at change (sets up g62)"},
  {"id":"ep-044","cat":"keep-it-equal","type":"strike-rewrite","hook":"\"Once we agree a split, it's sorted forever.\"","myth":{"un":"Once we agree a split, it's sorted forever.","re":"Equality is renegotiated as life changes; it's an ongoing conversation, not a one-time deal.","why":"Life keeps shifting the workload."},"relearn":"Equality is renegotiated as life changes; it's an ongoing conversation, not one-time.","persona":"any","source":"ongoing conversation"},
  {"id":"ep-045","cat":"keep-it-equal","type":"role-play","hook":"You want to set up regular check-ins on how the load is shared.","setup":"Propose it simply. Say:","yourLine":[{"text":"\"Can we check in monthly on how we're sharing things, and adjust if it's drifted?\"","best":true},{"text":"Only raise it when resentment boils over"}],"relearn":"Propose regular check-ins to keep the load fair and adjust drift early.","persona":"any","source":"check-ins"},
  {"id":"ep-046","cat":"keep-it-equal","type":"branch","hook":"Your fair split has slowly slipped back to old patterns.","options":[{"text":"Notice it and rebalance without blame","consequence":"You catch the drift early.","outcome":"rebalanced","best":true},{"text":"Let it quietly slide back","consequence":"Noticing and rebalancing without blame catches the drift before resentment sets in."}],"debrief":"Fairness drifts back to old patterns unless couples notice and rebalance regularly.","relearn":"Notice when the split slips back, and rebalance it without blame.","persona":"Pooja","source":"catching drift"},
  {"id":"ep-047","cat":"keep-it-equal","type":"reflect","hook":"Sam: an equal home is happier, less resentful and healthier for both of you. Worth building?","prompt":"What do you think?","options":["Yes","Happier for both","Worth it"],"affirm":"Equal homes are genuinely happier and less resentful; the effort pays off for both partners.","relearn":"An equal home is happier, less resentful and healthier for both partners.","persona":"any","source":"everyone gains"},
  {"id":"ep-048","cat":"keep-it-equal","type":"reflect","hook":"Sam: a child who grows up seeing equal parents learns it as normal. Worth modelling?","prompt":"What do you think?","options":["Yes","Model it","Normal for them"],"affirm":"Children who see equal parents grow up expecting equality; you model the future by living it.","relearn":"Children who see equal parents learn equality as normal; modelling it matters.","persona":"any","source":"modelling for kids"},
  {"id":"ep-049","cat":"keep-it-equal","type":"role-play","hook":"Your partner has taken on more lately; you want to acknowledge and rebalance.","setup":"Notice and offer. Say:","yourLine":[{"text":"\"You've been carrying more lately, let me take some back so it's even again.\"","best":true},{"text":"Not notice and leave it on them"}],"relearn":"Notice when your partner's carrying more, and offer to take some back.","persona":"any","source":"noticing and offering"},
  {"id":"ep-050","cat":"keep-it-equal","type":"branch","hook":"Resentment about the unequal load is starting to hurt your relationship.","options":[{"text":"Address the fairness directly, kindly, before it festers","consequence":"You protect the relationship.","outcome":"protected","best":true},{"text":"Let the resentment simmer","consequence":"Addressing fairness directly and kindly protects the relationship that simmering resentment erodes."}],"debrief":"Unaddressed load-inequality breeds resentment; naming and fixing it protects the partnership.","relearn":"Address load-unfairness kindly before resentment damages the relationship.","persona":"Saxena","source":"before it festers"},
  {"id":"ep-051","cat":"tools-and-help","type":"match","hook":"Match the tool to what it helps with.","pairs":[{"left":"A full load inventory","right":"Seeing the invisible work"},{"left":"An owned-domains split","right":"Sharing the mental load"},{"left":"A monthly check-in","right":"Keeping it fair over time"}],"relearn":"A load inventory, an owned-domains split and a check-in each move a home toward fairness.","persona":"any","source":"the tools"},
  {"id":"ep-052","cat":"tools-and-help","type":"sort","hook":"Sort: moves the home toward equal, or keeps it unequal?","items":[{"id":"a","text":"Owning domains end-to-end"},{"id":"b","text":"'Helping' when asked"},{"id":"c","text":"Sharing the mental load"},{"id":"d","text":"One person managing it all"}],"bins":[{"id":"equal","label":"Toward equal"},{"id":"unequal","label":"Keeps unequal"}],"key":{"a":"equal","b":"unequal","c":"equal","d":"unequal"},"relearn":"Owning domains and sharing the mental load moves toward equal; 'helping' when asked and one manager keeps it unequal.","persona":"any","source":"toward equal"},
  {"id":"ep-053","cat":"tools-and-help","type":"reflect","hook":"Sam: this isn't about men vs women, it's about a fairer, happier home for both. Agree?","prompt":"What do you think?","options":["Yes","For both","Not men vs women"],"affirm":"An equal home isn't a battle of the sexes; it's a better life for everyone in it.","relearn":"An equal home isn't men vs women; it's fairer and happier for both.","persona":"Karthik","source":"for everyone"},
  {"id":"ep-054","cat":"tools-and-help","type":"strike-rewrite","hook":"\"An equal home is just a women's demand and a loss for men.\"","myth":{"un":"An equal home is a women's demand and a loss for men.","re":"An equal home is happier and healthier for everyone; men gain deeper connection and a fairer life too.","why":"Fairness lifts both partners, not one at the other's cost."},"relearn":"An equal home gains everyone; men get deeper connection and a fairer life, not a loss.","persona":"Karthik","source":"men gain too"},
  {"id":"ep-055","cat":"tools-and-help","type":"role-play","hook":"A friend's home load is crushingly unequal and she feels alone in it.","setup":"Give her language and support. Say:","yourLine":[{"text":"\"That's the mental load, and it's real, you deserve a partner who owns half, not just helps.\"","best":true},{"text":"\"That's just how marriage is.\""}],"relearn":"Name the mental load with a struggling friend and share what helps.","persona":"any","source":"supporting a friend"},
  {"id":"ep-056","cat":"tools-and-help","type":"reflect","hook":"Sam: when inequality at home becomes control or coercion, that's abuse, and there's help. Clear?","prompt":"What do you think?","options":["Yes","That's abuse","Help exists"],"affirm":"Inequality that tips into control or coercion is abuse, not just unfairness, and help is there (see Respect at Home).","relearn":"When home inequality becomes control or coercion, that's abuse, and help exists.","persona":"any","source":"links to g56/help"},
  {"id":"ep-057","cat":"tools-and-help","type":"match","hook":"Match the need to the route.","pairs":[{"left":"A drifted, unfair split","right":"A fair-split renegotiation"},{"left":"Coercive control over money/home","right":"Respect at Home (g56) & help"},{"left":"A struggling partnership","right":"A couples counsellor"}],"relearn":"Renegotiate a drifted split, route coercive control to g56/help, and a counsellor for a struggling partnership.","persona":"any","source":"routes"},
  {"id":"ep-058","cat":"tools-and-help","type":"spot","hook":"Spot the message that builds an equal home.","scene":[{"id":"a","text":"\"Let's share the invisible load too\"","trick":false},{"id":"b","text":"\"You're better at the home stuff\"","trick":true},{"id":"c","text":"\"I'll own this, you don't manage it\"","trick":false}],"why":"Sharing the invisible load and owning a domain builds equality; 'you're better at home stuff' entrenches the default.","relearn":"'Share the invisible load' and 'I'll own this' build an equal home; 'you're better at it' doesn't.","persona":"any","source":"building messages"},
  {"id":"ep-059","cat":"tools-and-help","type":"match","hook":"Match each 'equal partners' idea to what it changes.","pairs":[{"left":"See the invisible load","right":"You can share it"},{"left":"Own, don't just help","right":"You lift the load"},{"left":"Both careers count","right":"Neither sidelined"}],"relearn":"See the load, own don't help, value both careers, and renegotiate as life changes.","persona":"any","source":"carry home"},
  {"id":"ep-060","cat":"see-the-load","type":"branch","hook":"You genuinely thought the home was balanced until you really looked.","options":[{"text":"Take the new awareness seriously and change","consequence":"You turn seeing into doing.","outcome":"acts","best":true},{"text":"Feel defensive and dismiss it","consequence":"Taking the new awareness seriously and changing beats getting defensive once you've really seen the load."}],"debrief":"Seeing the imbalance is uncomfortable, but acting on it, not getting defensive, is what fixes it.","relearn":"Take new awareness of the imbalance seriously and act, rather than getting defensive.","persona":"Karthik","source":"act on awareness"},
  {"id":"ep-061","cat":"helping-vs-owning","type":"sort","hook":"Sort: truly owning it, or still a helper?","items":[{"id":"a","text":"You handle the school admin entirely"},{"id":"b","text":"You do school runs when reminded"},{"id":"c","text":"You plan and book the holidays"},{"id":"d","text":"You wait to be told the plan"}],"bins":[{"id":"owns","label":"Owning"},{"id":"helper","label":"Still a helper"}],"key":{"a":"owns","b":"helper","c":"owns","d":"helper"},"relearn":"Handling admin and planning entirely is owning; doing things only when reminded or told is still helping.","persona":"any","source":"owner or helper"},
  {"id":"ep-062","cat":"share-it-fairly","type":"reflect","hook":"Sam: fairness at home isn't a one-off settlement, it's a habit you keep choosing. Agree?","prompt":"What do you think?","options":["Yes","A habit","Keep choosing"],"affirm":"A fair home is a habit of ongoing fairness, chosen again and again, not a single settlement.","relearn":"Fairness at home is an ongoing habit, not a one-off settlement.","persona":"any","source":"a habit"},
  {"id":"ep-063","cat":"two-careers","type":"role-play","hook":"Your partner downplays her own career to prioritise yours by default.","setup":"Push back, supportively. Say:","yourLine":[{"text":"\"Your career matters as much as mine, let's not just default to mine.\"","best":true},{"text":"Quietly accept your career coming first"}],"relearn":"Affirm that your partner's career matters as much as yours; don't default to one.","persona":"Karthik","source":"valuing her career"},
  {"id":"ep-064","cat":"keep-it-equal","type":"sort","hook":"Sort: keeps a home equal over years, or lets it slide?","items":[{"id":"a","text":"Regular, honest check-ins"},{"id":"b","text":"Assuming it's fine forever"},{"id":"c","text":"Adjusting around big changes"},{"id":"d","text":"Ignoring slow drift"}],"bins":[{"id":"keeps","label":"Keeps it equal"},{"id":"slides","label":"Lets it slide"}],"key":{"a":"keeps","b":"slides","c":"keeps","d":"slides"},"relearn":"Check-ins and adjusting around change keep a home equal; assuming it's fine and ignoring drift lets it slide.","persona":"any","source":"over the years"},
  {"id":"ep-065","cat":"see-the-load","type":"strike-rewrite","hook":"\"If she doesn't complain, the load must be fair.\"","myth":{"un":"If she doesn't complain, the load must be fair.","re":"Many carry the load silently to avoid conflict; no complaint doesn't mean it's fair.","why":"Silence can be exhaustion, not contentment."},"relearn":"No complaint doesn't mean it's fair; many carry the load silently.","persona":"any","source":"silence isn't fairness"},
  {"id":"ep-066","cat":"helping-vs-owning","type":"branch","hook":"You catch yourself saying 'just tell me what to do' about the home.","options":[{"text":"Switch to figuring out what's needed yourself","consequence":"You take on the noticing, not just the doing.","outcome":"owns","best":true},{"text":"Keep waiting for instructions","consequence":"Figuring out what's needed yourself takes on the noticing; 'just tell me' keeps the load on your partner."}],"debrief":"'Just tell me what to do' keeps your partner as the manager; figuring it out yourself is owning.","relearn":"Replace 'just tell me what to do' with figuring out what's needed yourself.","persona":"Karthik","source":"stop asking what to do"},
  {"id":"ep-067","cat":"share-it-fairly","type":"branch","hook":"You're dividing the load but keep landing the woman with the unpleasant tasks.","options":[{"text":"Share the unpleasant and invisible tasks too, fairly","consequence":"You make the split genuinely fair.","outcome":"fair","best":true},{"text":"Let her keep the worst of it","consequence":"Sharing the unpleasant and invisible tasks too, not just the easy visible ones, makes the split genuinely fair."}],"debrief":"A fair split shares the unpleasant and invisible tasks, not just the pleasant visible ones.","relearn":"Share the unpleasant and invisible tasks fairly too, not just the easy ones.","persona":"any","source":"share the worst too"},
  {"id":"ep-068","cat":"two-careers","type":"strike-rewrite","hook":"\"One strong career propped up by the other's unpaid work is as good as two.\"","myth":{"un":"One strong career propped up by the other's unpaid work is as good as two.","re":"Two mutually-supported careers go further than one carried on the other's unpaid labour.","why":"Propping one up wastes the other's potential."},"relearn":"Two mutually-supported careers go further than one carried on the other's unpaid work.","persona":"any","source":"mutual support"},
  {"id":"ep-069","cat":"keep-it-equal","type":"match","hook":"Match the concrete habit to what it makes durable.","pairs":[{"left":"Owned domains","right":"No one left managing"},{"left":"Regular check-ins","right":"Catches drift early"},{"left":"Agreed standards","right":"No hidden re-work"}],"relearn":"Concrete habits, owned domains, check-ins and agreed standards, make equality stick.","persona":"any","source":"make it stick"},
  {"id":"ep-070","cat":"helping-vs-owning","type":"spot","hook":"Spot the sign you've truly shared the load.","scene":[{"id":"a","text":"Your partner never thinks about what you own","trick":false},{"id":"b","text":"Your partner still reminds you","trick":true},{"id":"c","text":"You notice and act without prompting","trick":false}],"why":"Your partner never having to think about your domain, and you acting unprompted, means you've shared it; still needing reminders means you haven't.","relearn":"True owning means your partner never has to think about that domain at all.","persona":"any","source":"the clear target"},
  {"id":"ep-071","cat":"see-the-load","type":"reflect","hook":"Sam: naming the invisible load out loud is half the battle, it stops being invisible. Agree?","prompt":"What do you think?","options":["Yes","Name it out loud","Half the battle"],"affirm":"Saying the invisible load out loud is most of the work; once named, it can finally be shared.","relearn":"Naming the invisible load out loud stops it being invisible, that's half the battle.","persona":"Pooja","source":"name it out loud"},
  {"id":"ep-072","cat":"share-it-fairly","type":"spot","hook":"Spot the move that prevents hidden extra load.","scene":[{"id":"a","text":"Agreeing shared standards together","trick":false},{"id":"b","text":"One person silently redoing the other's work","trick":true},{"id":"c","text":"Both accepting 'good enough'","trick":false}],"why":"Agreed standards and accepting 'good enough' prevent hidden re-work; silently redoing creates it.","relearn":"Agree shared standards so neither silently redoes the other's work.","persona":"any","source":"shared standards"},
  {"id":"ep-073","cat":"two-careers","type":"sort","hook":"Sort: an equal-careers belief, or a bias?","items":[{"id":"a","text":"Both jobs deserve real support"},{"id":"b","text":"Her job is just 'pocket money'"},{"id":"c","text":"Either career can be the priority"},{"id":"d","text":"His ambitions always come first"}],"bins":[{"id":"equal","label":"Equal-careers"},{"id":"bias","label":"Bias"}],"key":{"a":"equal","b":"bias","c":"equal","d":"bias"},"relearn":"Both jobs deserving support and either being the priority is equal; 'pocket money' and his-always-first is bias.","persona":"any","source":"belief or bias"},
  {"id":"ep-074","cat":"keep-it-equal","type":"reflect","hook":"Sam: an equal home is something you build together, over years, on purpose. Ready to keep at it?","prompt":"What do you think?","options":["Yes","Build it together","Keep at it"],"affirm":"An equal home is a shared, ongoing project; staying at it together is exactly how it's built.","relearn":"An equal home is built together, over years, on purpose.","persona":"any","source":"build it together"},
  {"id":"ep-075","cat":"tools-and-help","type":"sort","hook":"Sort: this game's stance, or against it?","items":[{"id":"a","text":"Men owning an equal share"},{"id":"b","text":"Shaming a couple's current setup"},{"id":"c","text":"Making the invisible load visible"},{"id":"d","text":"Treating it as a women-only issue"}],"bins":[{"id":"for","label":"The stance"},{"id":"against","label":"Against it"}],"key":{"a":"for","b":"against","c":"for","d":"against"},"relearn":"Men owning an equal share and making the load visible is the stance; shaming setups or women-only framing isn't.","persona":"any","source":"the stance"},
  {"id":"ep-076","cat":"helping-vs-owning","type":"role-play","hook":"Your partner says 'it's easier if I just do it myself'.","setup":"Take real ownership so that changes. Say:","yourLine":[{"text":"\"Let me own this properly so it's genuinely off your plate, not easier to just do yourself.\"","best":true},{"text":"\"Okay, if it's easier for you.\""}],"relearn":"When 'easier to do it myself' appears, take real ownership so it's genuinely off their plate.","persona":"Karthik","source":"taking it off their plate"},
  {"id":"ep-077","cat":"see-the-load","type":"role-play","hook":"You want to finally see the mental load you've been blind to.","setup":"Ask your partner to show you. Say:","yourLine":[{"text":"\"Can you walk me through the invisible stuff you handle in a day? I want to really see it.\"","best":true},{"text":"Assume you already know it all"}],"relearn":"Ask your partner to narrate a day's invisible work to see the mental load.","persona":"Karthik","source":"narrate the day"},
  {"id":"ep-078","cat":"share-it-fairly","type":"match","hook":"Match the split principle to what it ensures.","pairs":[{"left":"Own whole domains","right":"No one's left managing"},{"left":"Count all hours","right":"Fair, not just visible"},{"left":"Agree, don't assume","right":"Genuine fairness"}],"relearn":"Owning domains, counting all hours and agreeing explicitly each ensure a genuinely fair split.","persona":"any","source":"split principles"},
  {"id":"ep-079","cat":"keep-it-equal","type":"branch","hook":"You slipped back into old patterns and your partner's quietly resentful again.","options":[{"text":"Own the slip, apologise, and rebalance","consequence":"You repair and reset fairly.","outcome":"repaired","best":true},{"text":"Get defensive about how much you do","consequence":"Owning the slip and rebalancing repairs it; getting defensive about your contribution deepens the resentment."}],"debrief":"Slips happen; owning them and rebalancing, not defending, keeps the partnership fair and warm.","relearn":"Own a slip back into old patterns, apologise, and rebalance.","persona":"any","source":"owning a slip"},
  {"id":"ep-080","cat":"two-careers","type":"role-play","hook":"Relatives assume your wife will quit work once you have kids.","setup":"Set it straight, respectfully. Say:","yourLine":[{"text":"\"That'll be a decision we make together, her career matters as much as mine.\"","best":true},{"text":"Let the assumption stand"}],"relearn":"Make clear whether anyone steps back for kids is a joint decision, not assumed.","persona":"Karthik","source":"joint decision"},
  {"id":"ep-081","cat":"tools-and-help","type":"reflect","hook":"Sam: a truly equal home might be the most loving thing you build together. Believe it?","prompt":"What do you think?","options":["Yes","Most loving","Build it"],"affirm":"Sharing the load fully is a deep act of love and respect; it's one of the best things you can build.","relearn":"A truly equal home is one of the most loving things you can build together.","persona":"any","source":"loving home"},
  {"id":"ep-082","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"Some people are just naturally better at running a home.\"","myth":{"un":"Some people are just naturally better at running a home.","re":"Running a home is a learnable skill, not an inborn gift; anyone can build the habit of owning it.","why":"'Naturally better' is usually just more practice, often forced."},"relearn":"Running a home is a learnable skill, not an inborn gift; anyone can own it.","persona":"Karthik","source":"it's learnable"},
  {"id":"ep-083","cat":"share-it-fairly","type":"spot","hook":"Spot the genuinely fair split.","scene":[{"id":"a","text":"Owned domains plus shared mental load","trick":false},{"id":"b","text":"She manages, he does tasks when told","trick":true},{"id":"c","text":"All hours counted and balanced","trick":false}],"why":"Owned domains with shared mental load and all-hours-counted is fair; she-manages-he-does-when-told isn't.","relearn":"A fair split owns domains, shares the mental load and counts all hours.","persona":"any","source":"fair split"},
  {"id":"ep-084","cat":"tools-and-help","type":"reflect","hook":"Sam: see the load, own your half, value both careers, keep it equal, carry which home?","prompt":"What will you carry?","options":["See the invisible load","Own, don't just help","Value both careers","Keep renegotiating"],"affirm":"Carry that one home, and you build the equal, happier partnership this whole chapter is about.","relearn":"See the load, own your half, value both careers, and keep it equal.","persona":"any","source":"carry forward"},
];

